"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[2774],{2716(e,t,n){n.r(t),n.d(t,{assets:()=>d,contentTitle:()=>c,default:()=>h,frontMatter:()=>l,metadata:()=>s,toc:()=>p});const s=JSON.parse('{"id":"part2-backend-platform-security/fastapi-uvicorn-basics","title":"FastAPI & Uvicorn Basics","description":"A modern Python web framework for building APIs. You write endpoint functions with Python type hints, and FastAPI uses them to validate requests, serialize responses, and generate interactive API docs automatically.","source":"@site/docs/part2-backend-platform-security/01-fastapi-uvicorn-basics.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/01-fastapi-uvicorn-basics","permalink":"/tutorials/part2-backend-platform-security/01-fastapi-uvicorn-basics","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":1,"frontMatter":{"title":"FastAPI & Uvicorn Basics","slug":"/part2-backend-platform-security/01-fastapi-uvicorn-basics","description":"A modern Python web framework for building APIs. You write endpoint functions with Python type hints, and FastAPI uses them to validate requests, serialize responses, and generate interactive API docs automatically.","sidebar_label":"1. FastAPI and Uvicorn basics","pagination_label":"1. FastAPI and Uvicorn basics","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"Part overview","permalink":"/tutorials/part2-backend-platform-security/overview"},"next":{"title":"2. HTTP methods","permalink":"/tutorials/part2-backend-platform-security/02-http-methods"}}');var o=n(4848),a=n(8453),r=n(8172);const i=JSON.parse('{"sourcePath":"part2-backend-platform-security/01-fastapi-uvicorn-basics.html","route":"/part2-backend-platform-security/01-fastapi-uvicorn-basics","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"FastAPI & Uvicorn Basics","title":"FastAPI & Uvicorn Basics","description":"A modern Python web framework for building APIs. You write endpoint functions with Python type hints, and FastAPI uses them to validate requests, serialize responses, and generate interactive API docs automatically.","readingMinutes":3,"bodyClass":"","normalizeMath":false,"toc":[{"id":"definitions","label":"Definitions"},{"id":"why-fastapi-uvicorn","label":"Why FastAPI + Uvicorn"},{"id":"mini-tutorial-http-methods","label":"Mini Tutorial: HTTP Methods"},{"id":"the-common-http-methods","label":"The Common HTTP Methods"},{"id":"a-quick-mental-model-for-your-project","label":"A Quick Mental Model for Your Project"}],"html":"<div class=\\"container\\">\\n        \\n\\n        <h2 id=\\"definitions\\">Definitions</h2>\\n\\n        <h3 id=\\"fastapi\\">FastAPI</h3>\\n        <p>A modern Python web framework for building APIs. You write endpoint functions with Python type hints, and FastAPI uses them to validate requests, serialize responses, and generate interactive API docs automatically.</p>\\n\\n        <h3 id=\\"uvicorn\\">Uvicorn</h3>\\n        <p>A fast ASGI server. It\u2019s the program that actually runs your FastAPI app and handles incoming network connections (HTTP/WebSockets), passing requests into your app and sending responses back out.</p>\\n\\n        <h3 id=\\"asgi\\">ASGI</h3>\\n        <p>Asynchronous Server Gateway Interface: a standard way for an async Python web app (FastAPI/Starlette) to communicate with an async web server (Uvicorn).</p>\\n\\n        <h2 id=\\"why-fastapi-uvicorn\\">Why FastAPI + Uvicorn</h2>\\n        <ul>\\n            <li><strong>FastAPI</strong> gives you the API framework (routing, validation, docs, dependency injection).</li>\\n            <li><strong>Uvicorn</strong> gives you the server runtime to serve it efficiently.</li>\\n            <li><strong>ASGI</strong> is the glue that enables async concurrency and things like WebSockets (useful for real-time apps).</li>\\n        </ul>\\n\\n        <hr>\\n\\n        <h2 id=\\"mini-tutorial-http-methods\\">Mini Tutorial: HTTP Methods</h2>\\n        <p class=\\"note\\">(GET / POST / PUT / PATCH / DELETE) + \u201csafe\u201d + \u201cidempotent\u201d (FastAPI context)</p>\\n\\n        <h3 id=\\"anatomy-of-an-http-request\\">Anatomy of an HTTP Request</h3>\\n        <ul>\\n            <li><strong>Method</strong> (GET/POST/PUT/\u2026): the intent</li>\\n            <li><strong>URL</strong> (e.g. <code>/documents/123</code>): the target resource</li>\\n            <li><strong>Headers</strong> (e.g. <code>Authorization</code>)</li>\\n            <li><strong>Body</strong> (optional JSON): the data you send</li>\\n        </ul>\\n\\n        <h3 id=\\"why-there-are-different-http-methods\\">Why there are different HTTP methods</h3>\\n        <p>HTTP has different methods because they communicate the intent of a request in a standardized way:</p>\\n        <ul>\\n            <li><strong>Safety</strong>: Some requests are meant to be read-only (GET) vs change data (POST/PUT/PATCH/DELETE).</li>\\n            <li><strong>Retries</strong>: Some operations are designed to be safe to repeat (PUT/DELETE are typically idempotent), which matters when networks fail.</li>\\n            <li><strong>Caching</strong>: Reads (GET) can be cached by browsers/CDNs/proxies; writes usually aren\u2019t.</li>\\n            <li><strong>Tooling &amp; clarity</strong>: The method + URL together form a clear contract (<code>GET /documents/123</code> vs <code>DELETE /documents/123</code>), which helps docs, clients, gateways, and debugging.</li>\\n        </ul>\\n\\n        <h3 id=\\"concepts\\">Concepts</h3>\\n\\n        <h4>What \u201csafe\u201d means</h4>\\n        <p>A safe method should not change server state.</p>\\n        <ul>\\n            <li><strong>Safe</strong>: GET, HEAD</li>\\n            <li><strong>Not safe</strong>: POST, PUT, PATCH, DELETE</li>\\n        </ul>\\n        <p class=\\"note\\">Why it matters: systems may prefetch, cache, or retry safe requests more freely because they shouldn\u2019t cause side effects.</p>\\n\\n        <h4>What \u201cidempotent\u201d means</h4>\\n        <p>An idempotent method means repeating the same request leads to the same final server state.</p>\\n        <ul>\\n            <li><strong>Idempotent</strong>: GET, HEAD, PUT, DELETE (PATCH is often idempotent if it \u201csets fields\u201d, but not always)</li>\\n            <li><strong>Usually not idempotent</strong>: POST (repeating can create duplicates)</li>\\n        </ul>\\n        <p class=\\"note\\">Why it matters: when a client times out, it might retry. Retrying idempotent operations is safer.</p>\\n\\n        <hr>\\n\\n        <h2 id=\\"the-common-http-methods\\">The Common HTTP Methods</h2>\\n        <p class=\\"note\\">(What they mean + when to use)</p>\\n\\n        \x3c!-- GET --\x3e\\n        <div class=\\"method-card\\">\\n            <div class=\\"method-header\\">\\n                <span class=\\"method-badge\\" style=\\"background-color: #61affe;\\">GET</span>\\n                <strong>\u201cGive me data\u201d (read-only)</strong>\\n            </div>\\n            <ul>\\n                <li><strong>Meaning</strong>: Retrieve a resource (or list/search results)</li>\\n                <li><strong>Safe</strong>: yes</li>\\n                <li><strong>Idempotent</strong>: yes</li>\\n                <li><strong>Cacheable</strong>: often</li>\\n                <li><strong>Use for</strong>: fetching documents, listing, searching with simple query params</li>\\n            </ul>\\n            <p><strong>Example</strong>: <code>GET /documents/123</code></p>\\n            \\n            <h4>Client call</h4>\\n<pre>curl -H \\"Authorization: Bearer $TOKEN\\" \\\\\\n  http://localhost:8000/documents/123</pre>\\n\\n            <h4>FastAPI</h4>\\n<pre>@app.get(\\"/documents/{doc_id}\\")\\ndef get_document(doc_id: int):\\n    return {\\"id\\": doc_id, \\"title\\": \\"Example\\"}</pre>\\n        </div>\\n\\n        \x3c!-- POST --\x3e\\n        <div class=\\"method-card\\">\\n            <div class=\\"method-header\\">\\n                <span class=\\"method-badge\\" style=\\"background-color: #49cc90;\\">POST</span>\\n                <strong>\u201cCreate or perform an action\u201d</strong>\\n            </div>\\n            <ul>\\n                <li><strong>Meaning</strong>: Submit data to create something or run a server action</li>\\n                <li><strong>Safe</strong>: <span class=\\"cross\\">\u274c</span></li>\\n                <li><strong>Idempotent</strong>: <span class=\\"cross\\">\u274c</span> (usually)</li>\\n                <li><strong>Cacheable</strong>: usually <span class=\\"cross\\">\u274c</span></li>\\n                <li><strong>Use for</strong>: creating resources (<code>POST /documents</code>) or \u201ccommands\u201d like Q&amp;A query (<code>POST /query</code>)</li>\\n            </ul>\\n            <p><strong>Example</strong>: <code>POST /query</code> with a question in JSON</p>\\n\\n            <h4>Client call</h4>\\n<pre>curl -X POST http://localhost:8000/query \\\\\\n  -H \\"Authorization: Bearer $TOKEN\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\"question\\":\\"What does my policy say about refunds?\\"}\'</pre>\\n\\n            <h4>FastAPI</h4>\\n<pre>from pydantic import BaseModel\\n\\nclass QueryRequest(BaseModel):\\n    question: str\\n\\n@app.post(\\"/query\\")\\ndef query(req: QueryRequest):\\n    return {\\"answer\\": \\"Mock answer\\", \\"question\\": req.question}</pre>\\n        </div>\\n\\n        \x3c!-- PUT --\x3e\\n        <div class=\\"method-card\\">\\n            <div class=\\"method-header\\">\\n                <span class=\\"method-badge\\" style=\\"background-color: #fca130;\\">PUT</span>\\n                <strong>\u201cReplace this resource completely\u201d</strong>\\n            </div>\\n            <ul>\\n                <li><strong>Meaning</strong>: Set the resource at this URL to exactly this representation</li>\\n                <li><strong>Safe</strong>: <span class=\\"cross\\">\u274c</span></li>\\n                <li><strong>Idempotent</strong>: yes (repeat = same final state)</li>\\n                <li><strong>Use for</strong>: full replacement updates</li>\\n            </ul>\\n            <p><strong>Example</strong>: <code>PUT /documents/123</code> with full document fields</p>\\n\\n            <h4>Client call</h4>\\n<pre>curl -X PUT http://localhost:8000/documents/123 \\\\\\n  -H \\"Authorization: Bearer $TOKEN\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\"title\\":\\"New title\\",\\"content\\":\\"Full content\\"}\'</pre>\\n        </div>\\n\\n        \x3c!-- PATCH --\x3e\\n        <div class=\\"method-card\\">\\n            <div class=\\"method-header\\">\\n                <span class=\\"method-badge\\" style=\\"background-color: #50e3c2; color: #333;\\">PATCH</span>\\n                <strong>\u201cUpdate part of this resource\u201d</strong>\\n            </div>\\n            <ul>\\n                <li><strong>Meaning</strong>: Modify only certain fields</li>\\n                <li><strong>Safe</strong>: <span class=\\"cross\\">\u274c</span></li>\\n                <li><strong>Idempotent</strong>: depends (often yes if it \u201csets\u201d fields)</li>\\n                <li><strong>Use for</strong>: small updates like renaming a document</li>\\n            </ul>\\n            <p><strong>Example</strong>: <code>PATCH /documents/123</code> with <code>{\\"title\\":\\"Renamed\\"}</code></p>\\n\\n            <h4>Client call</h4>\\n<pre>curl -X PATCH http://localhost:8000/documents/123 \\\\\\n  -H \\"Authorization: Bearer $TOKEN\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d \'{\\"title\\":\\"Renamed\\"}\'</pre>\\n        </div>\\n\\n        \x3c!-- DELETE --\x3e\\n        <div class=\\"method-card\\">\\n            <div class=\\"method-header\\">\\n                <span class=\\"method-badge\\" style=\\"background-color: #f93e3e;\\">DELETE</span>\\n                <strong>\u201cRemove this resource\u201d</strong>\\n            </div>\\n            <ul>\\n                <li><strong>Meaning</strong>: Delete the resource at this URL</li>\\n                <li><strong>Safe</strong>: <span class=\\"cross\\">\u274c</span></li>\\n                <li><strong>Idempotent</strong>: yes (deleting twice still ends \u201cdeleted\u201d)</li>\\n                <li><strong>Use for</strong>: deleting documents, records, jobs</li>\\n            </ul>\\n            <p><strong>Example</strong>: <code>DELETE /documents/123</code></p>\\n\\n            <h4>Client call</h4>\\n<pre>curl -X DELETE http://localhost:8000/documents/123 \\\\\\n  -H \\"Authorization: Bearer $TOKEN\\"</pre>\\n        </div>\\n\\n        <hr>\\n\\n        <h2 id=\\"a-quick-mental-model-for-your-project\\">A Quick Mental Model for Your Project</h2>\\n        <div class=\\"mental-model\\">\\n            <ul>\\n                <li>Use <strong>GET</strong> for fetching: document list/details, status checks.</li>\\n                <li>Use <strong>POST</strong> for actions: your Q&amp;A <code>/query</code> is naturally POST (complex body, not a simple \u201cresource fetch\u201d).</li>\\n                <li>Use <strong>PUT/PATCH</strong> for updating document metadata or settings.</li>\\n                <li>Use <strong>DELETE</strong> to remove a document or ingestion entry.</li>\\n            </ul>\\n        </div>\\n\\n        <div class=\\"tr-note\\">\\n          <strong>Chapter transition</strong>\\n          The next chapters separate HTTP method semantics from parameter\\n          placement, then map <code>/documents/{id}</code>,\\n          <code>?limit=</code>, headers, and JSON request models into typed\\n          FastAPI function arguments.\\n        </div>\\n    </div>"}'),l={title:"FastAPI & Uvicorn Basics",slug:"/part2-backend-platform-security/01-fastapi-uvicorn-basics",description:"A modern Python web framework for building APIs. You write endpoint functions with Python type hints, and FastAPI uses them to validate requests, serialize responses, and generate interactive API docs automatically.",sidebar_label:"1. FastAPI and Uvicorn basics",pagination_label:"1. FastAPI and Uvicorn basics",hide_title:!0,hide_table_of_contents:!0},c=void 0,d={},p=[];function u(e){return(0,o.jsx)(r.A,{content:i})}function h(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(u,{...e})}):u()}}}]);